package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.Flight;import com.makemytrip.makemytrip.models.PriceHistory;
import com.makemytrip.makemytrip.repositories.*;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PricingEngineTest {private PricingEngine engine(){PricingEngine p=new PricingEngine(mock(FlightRepository.class),mock(HotelRepository.class),mock(BookingRepository.class),mock(PriceHistoryRepository.class),mock(PricingRulesRepository.class));ReflectionTestUtils.setField(p,"holidayMultiplier",1.2);ReflectionTestUtils.setField(p,"demandMultiplier",1.1);ReflectionTestUtils.setField(p,"availabilityMultiplier",1.15);ReflectionTestUtils.setField(p,"leadTimeMultiplier",1.1);ReflectionTestUtils.setField(p,"demandThreshold",10L);ReflectionTestUtils.setField(p,"lowInventoryThreshold",3);return p;}@Test void basePriceHasNoMultiplier(){assertEquals(1,engine().calculateMultiplier(false,0,20,30));}@Test void holidayMultiplierIsTwentyPercent(){assertEquals(1.2,engine().calculateMultiplier(true,0,20,30),0.0001);}@Test void demandScarcityAndShortLeadTimeStackMultipliers(){assertEquals(1.1*1.15*1.1,engine().calculateMultiplier(false,10,2,2),0.0001);}
 @Test void calculatedPriceIsPersistedInHistoryWithAllPriceFields(){FlightRepository flights=mock(FlightRepository.class);BookingRepository bookings=mock(BookingRepository.class);PriceHistoryRepository history=mock(PriceHistoryRepository.class);PricingRulesRepository rules=mock(PricingRulesRepository.class);Flight flight=new Flight();flight.setId("f1");flight.setPrice(1000);flight.setAvailableSeats(20);flight.setDepartureTime(java.time.LocalDate.now().plusDays(10)+"T10:00");when(flights.findById("f1")).thenReturn(java.util.Optional.of(flight));when(rules.findById("default")).thenReturn(java.util.Optional.empty());when(bookings.countByFlightIdAndBookingDateAfter(eq("f1"),any())).thenReturn(0L);when(history.save(any())).thenAnswer(i->i.getArgument(0));PricingEngine pricing=new PricingEngine(flights,mock(HotelRepository.class),bookings,history,rules);org.springframework.test.util.ReflectionTestUtils.setField(pricing,"holidayMultiplier",1.2);org.springframework.test.util.ReflectionTestUtils.setField(pricing,"demandMultiplier",1.1);org.springframework.test.util.ReflectionTestUtils.setField(pricing,"availabilityMultiplier",1.15);org.springframework.test.util.ReflectionTestUtils.setField(pricing,"leadTimeMultiplier",1.1);org.springframework.test.util.ReflectionTestUtils.setField(pricing,"demandThreshold",10L);org.springframework.test.util.ReflectionTestUtils.setField(pricing,"lowInventoryThreshold",3);PriceHistory snapshot=pricing.currentFlight("f1");assertEquals(1000,snapshot.getBasePrice());assertEquals(1000,snapshot.getCurrentPrice());assertEquals(1,snapshot.getMultiplier());assertEquals("BASE_PRICE",snapshot.getReason());verify(history).save(any(PriceHistory.class));}}
